"""Reconstruct logical sticker assets from native visible-only parts.

Python 3.9+ and Pillow are required. All package paths are manifest-relative.
Example: python3 reconstruct.py manifest.json --output reconstructed.png
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import sys

from PIL import Image, ImageChops


class InvalidPackage(ValueError):
    pass


class UnsafeWritePath(InvalidPackage):
    pass


def integer(value, label, minimum=None):
    if type(value) is not int or (minimum is not None and value < minimum):
        raise InvalidPackage(f"{label}: expected integer" + (f" >= {minimum}" if minimum is not None else ""))
    return value


def text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise InvalidPackage(f"{label}: expected nonempty string")
    return value


def array(value, label):
    if not isinstance(value, list):
        raise InvalidPackage(f"{label}: expected array")
    return value


def obj(value, label):
    if not isinstance(value, dict):
        raise InvalidPackage(f"{label}: expected object")
    return value


def native_transform(entry, label):
    if type(entry.get("scale")) is bool or entry.get("scale") != 1:
        raise InvalidPackage(f"{label}.scale must be 1")
    if type(entry.get("rotation")) is bool or entry.get("rotation") != 0:
        raise InvalidPackage(f"{label}.rotation must be 0")


def package_path(root, value, label):
    relative = Path(text(value, label))
    path = (root / relative).resolve()
    if relative.is_absolute() or not path.is_relative_to(root):
        raise InvalidPackage(f"{label}: path must stay inside the manifest directory")
    if not path.is_file():
        raise InvalidPackage(f"{label}: file not found: {relative}")
    return path


def rgba_png(path, label):
    with Image.open(path) as image:
        image.load()
        if image.format != "PNG" or image.mode != "RGBA":
            raise InvalidPackage(f"{label}: expected native RGBA PNG, received {image.format}/{image.mode}")
        return image.copy()


def mask_png(path, label):
    with Image.open(path) as image:
        image.load()
        if image.format != "PNG":
            raise InvalidPackage(f"{label}: expected PNG mask")
        if "A" in image.getbands():
            return image.getchannel("A")
        if image.mode in {"1", "L"}:
            return image.convert("L")
        if image.mode == "RGB":
            red, green, blue = image.split()
            if ImageChops.difference(red, green).getbbox() or ImageChops.difference(red, blue).getbbox():
                raise InvalidPackage(f"{label}: RGB mask must have equal channels")
            return red
        raise InvalidPackage(f"{label}: use grayscale or alpha PNG")


def sha256_pixels(image):
    return hashlib.sha256(image.tobytes()).hexdigest()


def sha256_file(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def metrics(first, second, visible_mask=None):
    difference = ImageChops.difference(first, second)
    changed = difference.split()[0]
    for channel in difference.split()[1:]:
        changed = ImageChops.lighter(changed, channel)
    if visible_mask is not None:
        visible = visible_mask.point(lambda value: 255 if value else 0)
        changed = ImageChops.multiply(changed, visible)
    count = first.width * first.height - changed.histogram()[0]
    bounds = changed.getbbox()
    return {"mismatch_count": count, "max_absdiff": changed.getextrema()[1],
            "difference_bbox": list(bounds) if bounds else None}


def view_box(region, canvas_size):
    value = region.get("view_box")
    if isinstance(value, dict):
        values = [value.get(key) for key in ("x", "y", "width", "height")]
    else:
        values = array(value, f"region {region['id']}.view_box")
    if len(values) != 4:
        raise InvalidPackage(f"region {region['id']}.view_box must be [x,y,width,height]")
    x, y, width, height = [integer(value, f"region {region['id']}.view_box[{index}]", 1 if index > 1 else 0)
                           for index, value in enumerate(values)]
    if x + width > canvas_size[0] or y + height > canvas_size[1]:
        raise InvalidPackage(f"region {region['id']}.view_box exceeds canvas")
    return x, y, width, height


def region_checks(manifest, assets, canvas_size):
    by_id = {asset["id"]: asset for asset in assets}
    regions = array(manifest.get("regions"), "regions")
    region_ids = set()
    reports = []
    for index, raw in enumerate(regions):
        region = obj(raw, f"regions[{index}]")
        region_id = text(region.get("id"), f"regions[{index}].id")
        text(region.get("name"), f"region {region_id}.name")
        if region_id in region_ids:
            raise InvalidPackage(f"duplicate region id: {region_id}")
        region_ids.add(region_id)
        bounds = view_box(region, canvas_size)
        required = array(region.get("required_ids"), f"region {region_id}.required_ids")
        for required_id in required:
            text(required_id, f"region {region_id}.required_ids")
        if len(set(required)) != len(required):
            raise InvalidPackage(f"region {region_id}.required_ids contains duplicate IDs")
        declared = set(required)
        assigned = {asset["id"] for asset in assets if asset["region"] == region_id}
        missing = sorted(declared - by_id.keys())
        wrong_region = sorted(asset_id for asset_id in declared & by_id.keys()
                              if by_id[asset_id]["region"] != region_id)
        omitted = sorted(assigned - declared)
        vx, vy, vw, vh = bounds
        outside_view = sorted(asset_id for asset_id in declared & by_id.keys()
                              if not (by_id[asset_id]["x"] < vx + vw and
                                      by_id[asset_id]["x"] + by_id[asset_id]["width"] > vx and
                                      by_id[asset_id]["y"] < vy + vh and
                                      by_id[asset_id]["y"] + by_id[asset_id]["height"] > vy))
        complete = not (missing or wrong_region or omitted or outside_view)
        reports.append({"id": region_id, "name": region["name"], "view_box": list(bounds),
                        "next_region": region.get("next_region"), "required_count": len(required),
                        "present_required_count": len(declared & by_id.keys()),
                        "missing_ids": missing, "wrong_region_ids": wrong_region,
                        "omitted_assigned_ids": omitted, "outside_view_ids": outside_view,
                        "complete": complete})
    unknown_regions = sorted({asset["region"] for asset in assets} - region_ids)
    bad_next = []
    for region in reports:
        next_id = region["next_region"]
        if next_id is not None and (not isinstance(next_id, str) or next_id not in region_ids):
